    <script type="module">
        (async function() {
            /* 确保在MVU框架加载后再执行 */
            await waitGlobalInitialized('Mvu');

            const dataSource = document.getElementById('bounty-data-source');
            if (!dataSource) return;

            const rawText = dataSource.innerText;
            const bountyList = document.querySelector('#bounty-board-wrapper .bounty-list');

            /* 清洗并解析任务数据 */
            const tasks = rawText.match(/\[(.*?)\]/g)
                ?.map(line => line.slice(1, -1).split('|').map(s => s.trim()))
                .filter(parts => parts.length === 5) || [];

            if (tasks.length === 0) {
                bountyList.innerHTML = '<li>&gt; 系统离线或无可用任务...</li>';
                return;
            }

            tasks.forEach((taskData, index) => {
                const [title, faction, risk, reward, brief] = taskData;
                const card = document.createElement('li');
                card.className = 'bounty-card';
                card.innerHTML = `
                    <div class="bounty-card-header">
                        <span class="bounty-title">${title}</span>
                        <span class="bounty-faction">发布方: ${faction}</span>
                    </div>
                    <div class="bounty-brief">${brief}</div>
                    <div class="bounty-details">
                        <div class="detail-item">
                            <span class="detail-label">风险评级</span>
                            <span class="risk-level" data-risk="${risk}">${risk}</span>
                        </div>
                        <div class="detail-item">
                            <span class="detail-label">任务报酬</span>
                            <span>${reward}</span>
                        </div>
                    </div>
                    <div class="bounty-actions">
                        <button class="accept-btn" data-index="${index}">&lt; 接取任务 &gt;</button>
                    </div>
                `;
                bountyList.appendChild(card);
            });

            const acceptButtons = document.querySelectorAll('.accept-btn');

            acceptButtons.forEach(button => {
                button.addEventListener('click', async (e) => {
                    const btn = e.target;
                    try {
                        const currentMsgId = window.getCurrentMessageId();
                        const mvuData = Mvu.getMvuData({ type: 'message', message_id: currentMsgId });

                        const currentTasks = _.get(mvuData, 'stat_data.世界.任务日志', {});
                        if (Object.keys(currentTasks).length >= 3) {
                            triggerSlash('/echo severity=warning 任务日志已满 (最大3个)，请先完成或放弃任务。');
                            return;
                        }

                        const taskIndex = parseInt(btn.getAttribute('data-index'));
                        const selectedTask = tasks[taskIndex];
                        const [title, faction, risk, reward, brief] = selectedTask;

                        /* 使用 _.set 安全地添加新任务 */
                        _.set(mvuData, `stat_data.世界.任务日志.${title}`, {
                            状态: "进行中",
                            发布方: faction,
                            难度: risk,
                            报酬: reward,
                            当前目标: brief 
                        });

                        /* 写回更新后的变量 */
                        await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: currentMsgId });

                        /* UI反馈 */
                        triggerSlash(`/echo severity=success 任务“${title}”已添加至日志。`);
                        btn.textContent = "[状态：已记录]";
                        btn.disabled = true;
                        btn.closest('.bounty-card').classList.add('accepted');

                    } catch (error) {
                        console.error('接取任务失败:', error);
                        triggerSlash('/echo severity=error 系统错误：无法更新任务日志。');
                    }
                });
            });

        })();
    </script>
</body>
</html>
