    let currentFullContent = "";
    const skillIcons = {"潜行":"👤", "黑客技术":"💻", "机械维修":"🔧", "重火力":"💥", "医疗急救":"✚", "社交口才":"💬", "default":"Ø"};

    /* --- DOM ELEMENTS --- */
    const screens = { profile: document.getElementById('profile-screen'), lottery: document.getElementById('lottery-screen'), story: document.getElementById('story-screen') };
    const submitBtn = document.getElementById('submit-profile-btn');
    const rerollBtn = document.getElementById('reroll-btn');
    const acceptBtn = document.getElementById('accept-btn');
    const specIcon = document.getElementById('spec-icon');
    const systemStatus = document.querySelector('.system-status');

    /* --- HELPERS --- */
    const switchScreen = (screenName) => {
        Object.values(screens).forEach(s => s.classList.remove('active'));
        if (screens[screenName]) screens[screenName].classList.add('active');
    };

    const generateScenario = async () => {
        rerollBtn.disabled = true;
        acceptBtn.disabled = true;
        document.getElementById('lotto-synopsis').textContent = "正在生成新的开局...请稍候...";
        try {
            const rawResponse = await generate({ user_input: "##GENERATE_SCENARIO##", should_stream: false, should_silence: true });
            const responseText = (typeof rawResponse === 'string') ? rawResponse : (rawResponse?.response || "");

            const summaryMatch = responseText.match(/<summary>([\s\S]*?)<\/summary>/);
            const contentMatch = responseText.match(/<content>([\s\S]*?)<\/content>/);

            if (summaryMatch && contentMatch) {
                document.getElementById('lotto-synopsis').textContent = summaryMatch[1].trim();
                currentFullContent = contentMatch[1].trim();
            } else {
                throw new Error("AI响应格式不正确。");
            }
        } catch (error) {
            console.error("开场生成失败:", error);
            document.getElementById('lotto-synopsis').textContent = "错误: 开场生成失败，请稍后重试。";
            triggerSlash('/echo severity=error 无法生成开场，请检查AI连接和世界书配置。');
        } finally {
            rerollBtn.disabled = false;
            acceptBtn.disabled = false;
        }
    };

    const typeWriter = (element, text) => {
        let i = 0;
        const animationDuration = (text.length * 50) + 2000;
        const terminalContainer = document.querySelector('.terminal-container');
        terminalContainer.style.transition = `opacity ${animationDuration}ms`; 

        element.innerHTML = 'Receiving...<br>';
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()_+-=[]{}|;:,.<>/?';
        let scrambleInterval = setInterval(() => {
            let randomText = '';
            for (let j = 0; j < text.length; j++) {
                randomText += chars.charAt(Math.floor(Math.random() * chars.length));
            }
            element.innerHTML = `DECRYPTING...<br>${randomText}<span class="cursor"></span>`;
        }, 100);

        setTimeout(() => {
            clearInterval(scrambleInterval);
            element.innerHTML = '<span class="cursor"></span>';
            const cursor = element.querySelector('.cursor');

            function type() {
                if (i < text.length) {
                    cursor.insertAdjacentText('beforebegin', text.charAt(i));
                    i++;
                    setTimeout(type, 30); // Typing speed
                } else {
                    // Animation complete, no need to do anything else, the UI is now just text.
                }
            }
            type();
        }, 2000); // Scramble duration
    };

    /* --- EVENT HANDLERS --- */
    submitBtn.addEventListener('click', async () => {
        const skillsCheckbox = document.querySelectorAll('#user-skills input:checked');
        const traitsCheckbox = document.querySelectorAll('#user-traits input:checked');

        if (!document.getElementById('profile-form').checkValidity() || skillsCheckbox.length === 0 || skillsCheckbox.length > 3 || traitsCheckbox.length === 0) {
            triggerSlash('/echo severity=warning 请完成所有必填项，并确保技能选择在1-3个之间。');
            return;
        }

        submitBtn.disabled = true;
        submitBtn.textContent = "[ 档案已锁定 ]";

        const profile = {
            name: document.getElementById('user-name').value, age: document.getElementById('user-age').value, gender: document.getElementById('user-gender').value, identity: document.getElementById('user-identity').value, background: document.getElementById('user-background').value,
            skills: Array.from(skillsCheckbox).map(el => el.value),
            traits: Array.from(traitsCheckbox).map(el => el.value)
        };

        const primarySkill = profile.skills[0] || 'default';
        specIcon.textContent = skillIcons[primarySkill] || skillIcons.default;
        systemStatus.textContent = "SYS_STATUS: ONLINE";

        const profileJson = JSON.stringify(profile, null, 2).replace(/\|/g, '\\|');
