        setTimeout(() => {
            switchScreen('lottery');
            generateScenario();
        }, 500);
    });

    rerollBtn.addEventListener('click', generateScenario);
    acceptBtn.addEventListener('click', () => {
        switchScreen('story');
        typeWriter(document.getElementById('story-output'), currentFullContent);
    });

})();
